import json, random, hashlib
from collections import Counter
from pathlib import Path

def load(p):
    return [json.loads(l) for l in Path(p).read_text().splitlines() if l.strip()]

def prep(train, epochs=1):
    out=[]
    for _ in range(epochs):
        for it in train:
            e={'input':it['input'],'target':it['target']}
            if 'raw_question' in it: e['raw_question']=it['raw_question']
            out.append(e)
    return out

def bigrams(s):
    s=s.replace(' ','')
    return Counter(s[i:i+2] for i in range(len(s)-1)) or Counter([s])

def cos(a,b):
    if not a or not b: return 0.0
    inter=sum((a&b).values()); 
    import math
    return inter/math.sqrt(sum(a.values())*sum(b.values()))

DATA={'USPTO':'uspto','Symptom2Disease':'symptom_diagnosis','LawBench':'crime_prediction'}
for task, d in DATA.items():
    tr=load(f'/workspace/benchmark/data/{d}/train.jsonl')
    va=load(f'/workspace/benchmark/data/{d}/val.jsonl')
    mem=prep(tr)
    # raw_question = what is shown
